"""Complete and serialize 36 original rheumatoid arthritis questions."""
from create_rheum_ra_treatment import rows,q,C,E,A,I,M,B,P,ref
from qbank_authoring import finalize

q('A woman with RA taking methotrexate wants to conceive. Which plan is most appropriate?', 'Arrange preconception review, discontinue methotrexate before attempting pregnancy and establish pregnancy-compatible disease control',[
 ('Continue methotrexate until the third trimester','Methotrexate is not compatible with planned pregnancy.'),('Stop all RA therapy indefinitely, even if disease becomes highly active','Uncontrolled maternal inflammatory disease also carries risk; compatible treatment should be planned.'),('Replace methotrexate with leflunomide immediately before conception','Leflunomide is also unsuitable without appropriate discontinuation and elimination procedures.')],
 'Plan disease control before conception','**Methotrexate must be stopped before planned pregnancy.**',['Discuss the recommended preconception interval using the relevant guideline and product information.','Hydroxychloroquine, sulfasalazine with appropriate folate and selected biologics can provide compatible options depending on the patient.'], '**Avoid a gap in effective care.**',['Coordinate rheumatology and obstetric review and discuss contraception until the plan is complete.','Breastfeeding compatibility requires a separate medication review.'],[['Methotrexate','Not pregnancy-compatible'],['Leflunomide','Requires discontinuation/elimination planning'],['Compatible alternatives','Select for disease and maternal factors']],[P,M],style='clinical_scenario')

q('Why may a cholestyramine elimination procedure be needed after stopping leflunomide for pregnancy planning or serious toxicity?', 'Its active metabolite can persist because of slow elimination and enterohepatic recycling',[
 ('Cholestyramine directly stimulates synovial repair','Its role here is drug elimination, not joint regeneration.'),('Leflunomide disappears completely within hours without intervention','Persistence can be prolonged in the absence of accelerated elimination.'),('Cholestyramine neutralizes circulating anti-CCP antibodies','It is not an antibody-removing treatment.')],
 'Stopping the tablet may not promptly end exposure','**Leflunomide metabolites can remain in the body for a prolonged period.**',['The product label describes cholestyramine 8 g three times daily for 11 days as an accelerated procedure.','Pregnancy-related clearance confirmation follows the specified drug-level protocol when available.'], '**Use a supervised elimination and follow-up plan.**',['Review liver injury, marrow toxicity or other reasons for discontinuation.','Disease activity may return as drug exposure falls, so plan alternative therapy.'],[['Drug persistence','Slow clearance/recycling'],['Cholestyramine','Accelerates elimination'],['Pregnancy planning','Confirm required clearance criteria']],[ref('DailyMed leflunomide prescribing information','https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c66cacd1-93f7-483a-a2fc-aad53d5342b0')])

q('A 60-kg patient is prescribed hydroxychloroquine 400 mg every day for RA. Which issue should be reviewed?', 'The dose exceeds the usual retinal-safety recommendation of no more than 5 mg/kg/day actual body weight',[
 ('The dose is below 5 mg/kg/day because ideal body weight must always replace actual weight','The AAO recommendation uses real weight; 400/60 is approximately 6.7 mg/kg/day.'),('Retinal screening is unnecessary if visual acuity is normal','Early toxicity may be asymptomatic and requires sensitive screening.'),('Hydroxychloroquine has no cumulative retinal toxicity','Dose and duration are important risk factors.')],
 'Calculate dose against actual body weight','**A 400-mg daily dose in a 60-kg person is about 6.7 mg/kg/day.**',['Discuss a practical lower average daily dose with the prescriber.','Renal disease, duration, tamoxifen and older initiation age also influence risk.'], '**Arrange baseline and risk-appropriate retinal screening.**',['AAO 2025 revision prioritizes OCT and wide-pattern fundus autofluorescence.','Annual testing may be deferred during the first five years only in patients without significant risk factors.'],[['Actual weight','60 kg'],['400 mg/day','About 6.7 mg/kg/day'],['Usual upper recommendation','5 mg/kg/day']],[ref('AAO hydroxychloroquine retinal screening: 2025 revision','https://www.aao.org/education/clinical-statement/revised-recommendations-on-screening-chloroquine-h')],style='clinical_scenario')

q('A patient on methotrexate develops mouth ulcers, bruising and pancytopenia after receiving trimethoprim-sulfamethoxazole. Which explanation is most likely?', 'Additive antifolate effects and altered methotrexate handling causing severe marrow toxicity',[
 ('A benign expected effect that needs only reassurance','Pancytopenia and mucositis can represent serious toxicity.'),('An isolated uricosuric interaction causing gout','This does not explain the marrow and mucosal syndrome.'),('A predictable rise in anti-CCP from both medications','Antibody titers do not explain acute pancytopenia.')],
 'Recognize a potentially dangerous drug interaction','**Co-trimoxazole or trimethoprim with methotrexate can cause severe myelosuppression.**',['Review dose timing, renal function and all co-medications.','Mucositis can be an early toxicity clue rather than a minor unrelated symptom.'], '**Withhold implicated drugs and arrange urgent assessment.**',['Evaluate for infection and bleeding in a cytopenic patient.','Specialist-directed folinic acid rescue and supportive measures depend on severity.'],[['Mucositis','Possible antifolate toxicity'],['Pancytopenia','Urgent marrow safety concern'],['Renal impairment','Can increase methotrexate exposure']],[ref('Medsafe: methotrexate and trimethoprim/co-trimoxazole marrow toxicity','https://www.medsafe.govt.nz/profs/PUArticles/March2022/Bone-marrow-suppression-methotrexate-and-trimethoprim-or-co-trimoxazole.html')],style='clinical_scenario')

q('Before starting a TNF inhibitor in a patient with RA, which infection assessment is particularly important?', 'Evaluate for active tuberculosis and screen for latent TB infection, with preventive treatment when indicated',[
 ('Use a negative IGRA alone to exclude active TB in a symptomatic patient','IGRA does not rule out active disease, especially with immunosuppression.'),('Give latent-TB monotherapy immediately despite cough and an abnormal chest image without further assessment','Active TB must be evaluated before preventive monotherapy.'),('Wait for disseminated TB before considering preventive care','Screening aims to reduce the reactivation risk before treatment.')],
 'Screen before impairing granuloma defense','**TNF inhibition can increase TB reactivation and disseminated disease risk.**',['Assess exposure, symptoms, imaging and immune-based testing according to local guidance.','An immune test detects sensitization and does not by itself distinguish latent from active infection.'], '**If active disease is suspected, investigate it before labeling latent infection.**',['Plan preventive treatment and timing of immunosuppression with the relevant specialist.','Review hepatitis and vaccination status as part of broader preparation.'],[['IGRA/TST','Evidence of immune sensitization'],['Symptoms/imaging','Assess possible active disease'],['Preventive therapy','For eligible latent infection after active disease exclusion']],[ref('EULAR screening and prophylaxis of chronic/opportunistic infections','https://doi.org/10.1136/ard-2022-223335')])

q('A patient with RA is HBsAg negative, anti-HBc positive and has undetectable HBV DNA. Rituximab is planned. Which strategy is appropriate?', 'Arrange antiviral prophylaxis and monitoring because anti-CD20 therapy can reactivate resolved HBV',[
 ('No HBV plan is needed because HBsAg is negative','Resolved infection can reactivate under B-cell depletion.'),('HBV vaccination alone eliminates reactivation risk from prior infection','Vaccination does not substitute for prophylaxis in this setting.'),('Use a brief antibacterial course instead of an antiviral','Antibacterial therapy does not prevent HBV reactivation.')],
 'Resolved HBV still matters before anti-CD20 treatment','**Anti-HBc positivity identifies prior exposure and a clinically important reactivation risk with rituximab.**',['Coordinate high-barrier nucleos(t)ide antiviral selection and duration with hepatology.','The prophylaxis plan extends beyond the infusion course according to applicable guidance.'], '**Do not rely solely on baseline undetectable DNA.**',['Document HBsAg, anti-HBc and anti-HBs before therapy.','Continue laboratory monitoring according to the risk-based plan.'],[['HBsAg negative/anti-HBc positive','Prior infection can reactivate'],['Rituximab','High-risk B-cell depletion'],['Antiviral prophylaxis','Prevents reactivation risk more appropriately than vaccination alone']],[A],style='clinical_scenario')

q('A patient on tocilizumab presents with fever, tachycardia and new focal abdominal pain but a low CRP. Which interpretation is safest?', 'IL-6 blockade can blunt CRP; serious infection or gastrointestinal pathology still needs urgent evaluation',[
 ('The low CRP reliably excludes bacterial infection','Acute-phase suppression reduces the reliability of this reassurance.'),('The symptoms prove an uncomplicated RA flare','The focal abdominal and systemic findings need another explanation.'),('CRP suppression guarantees that bowel perforation cannot occur','Tocilizumab has recognized gastrointestinal perforation warnings, especially in relevant risk contexts.')],
 'Read biomarkers through the mechanism of treatment','**IL-6 receptor blockade can suppress the hepatic acute-phase response.**',['Clinical severity, examination, cultures and imaging may be more informative than CRP alone.','Consider diverticulitis, perforation and other urgent causes when the presentation warrants it.'], '**Do not delay assessment because an inflammatory marker is low.**',['Review immunosuppression during a serious infection.','Provide source-directed treatment and surgical evaluation when indicated.'],[['Low CRP on IL-6 blockade','May be pharmacological'],['Focal abdominal pain','Requires examination and appropriate imaging'],['Systemic instability','Urgent evaluation']],[ref('FDA prescribing information: Actemra','https://www.accessdata.fda.gov/drugsatfda_docs/label/2022/125276s134lbl.pdf')],style='clinical_scenario')

q('A patient with RA taking methotrexate and adalimumab is scheduled for uncomplicated elective total knee arthroplasty. Which general medication approach matches the ACR/AAHKS guideline?', 'Usually continue methotrexate and withhold adalimumab for a dosing interval, with restart based on healing and absence of infection',[
 ('Continue both without considering surgical timing or infection','The biologic is usually withheld around elective arthroplasty.'),('Stop methotrexate for six months but double adalimumab before surgery','This reverses the usual approach and unnecessarily risks disease flare and exposure.'),('Replace both drugs with indefinite high-dose prednisone','This adds infection and metabolic risk without a justified maintenance plan.')],
 'Conventional and biological DMARDs have different perioperative plans','**The arthroplasty guideline usually continues methotrexate but times surgery after a withheld biologic dosing interval.**',['For every-two-week adalimumab, surgery is generally planned in week three after the last dose.','Restart depends on wound healing and no evidence of infection, often around two weeks, rather than a fixed rule regardless of the wound.'], '**Individualize for infection, renal dysfunction and the procedure.**',['Communicate the plan between the surgeon and rheumatology team.','These recommendations concern elective hip/knee arthroplasty and should not be indiscriminately applied to every operation.'],[['Methotrexate','Usually continue'],['Adalimumab','Withhold through surgery; time after dosing interval'],['Restart','Healing and infection assessment']],[ref('ACR/AAHKS 2022 perioperative antirheumatic medication guideline','https://doi.org/10.1002/art.42140')],style='clinical_scenario')

q('Which combination is conventional triple-DMARD therapy for rheumatoid arthritis?', 'Methotrexate, sulfasalazine and hydroxychloroquine',[
 ('Methotrexate, adalimumab and etanercept','This contains two TNF biologics and is not conventional triple therapy.'),('Prednisone, ibuprofen and paracetamol','These do not constitute three conventional disease-modifying agents.'),('Rituximab, abatacept and tocilizumab','Combining three biologics is not this strategy and presents major safety concerns.')],
 'Know the components and the place of conventional combination therapy','**Triple therapy combines three csDMARDs with different actions.**',['It remains a potential strategy in selected patients, especially when cost or access affects choices.','The decision versus an advanced agent depends on activity, prior response, comorbidities and patient preferences.'], '**Apply the monitoring requirements of each drug.**',['Review methotrexate marrow/liver/renal safety and hydroxychloroquine retinal safety.','Sulfasalazine requires its own tolerability and laboratory review.'],[['Methotrexate','Anchor csDMARD'],['Sulfasalazine','Additional csDMARD'],['Hydroxychloroquine','Additional csDMARD']],[A])

q('Which issue should be addressed as part of long-term RA management even after swollen joints improve?', 'Cardiovascular risk, smoking, physical function and bone health',[
 ('Only RF normalization, regardless of function','RF negativity is not the comprehensive long-term goal.'),('Avoidance of all physical activity to prevent any joint movement','Appropriate exercise and rehabilitation support function.'),('Permanent bed rest whenever imaging shows an old erosion','Old structural damage requires individualized care, not automatic immobilization.')],
 'Disease control is broader than a joint count','**RA care includes prevention of systemic morbidity and preservation of function.**',['Inflammation and conventional risk factors both contribute to cardiovascular risk.','Glucocorticoid exposure, age and mobility affect fracture risk.'], '**Combine pharmacological treatment with rehabilitation and prevention.**',['Support smoking cessation, appropriate exercise, vaccination and risk-factor control.','Adapt activity and joint protection to symptoms, damage and physical capacity.'],[['Cardiovascular health','Assess and modify risk'],['Bone health','Evaluate fracture risk'],['Function','Exercise, rehabilitation and joint protection']],[ref('EULAR cardiovascular risk management in inflammatory joint disorders','https://doi.org/10.1136/annrheumdis-2016-209775'),ref('EULAR physical activity recommendations for inflammatory arthritis','https://doi.org/10.1136/annrheumdis-2018-213585')])

q('A patient has RA controlled clinically but persistent widespread pain, fatigue, unrefreshing sleep and tenderness without swollen joints. What is the most appropriate next step?', 'Assess noninflammatory pain mechanisms and comorbid fibromyalgia before escalating immunosuppression',[
 ('Escalate to two biologics because tenderness always proves active synovitis','Tenderness alone may reflect central pain amplification or other causes.'),('Declare that normal CRP excludes all future RA activity','Inflammatory markers are imperfect and do not remove the need for examination and follow-up.'),('Stop all monitoring because RA can never relapse in this setting','Both inflammatory disease and comorbid pain require ongoing assessment.')],
 'Treat the cause of residual symptoms','**Pain can persist without active synovial inflammation.**',['Fibromyalgia, osteoarthritis, neuropathy and structural damage may inflate patient-reported disease activity.','If uncertainty persists, targeted imaging can supplement examination.'], '**Match treatment to the identified mechanism.**',['Discuss sleep, graded activity and multidisciplinary pain strategies when appropriate.','Maintain surveillance for objective evidence of inflammatory relapse.'],[['Swollen joints/Doppler synovitis','Supports active inflammation'],['Widespread tenderness and sleep disturbance','Suggests an additional pain mechanism'],['Treatment escalation','Should follow evidence of inflammatory activity']],[ref('EULAR points to consider for difficult-to-treat rheumatoid arthritis','https://pmc.ncbi.nlm.nih.gov/articles/PMC8761998/')],style='clinical_scenario')

q('Which finding most strongly suggests rheumatoid nodules rather than tophi in a patient with established seropositive RA?', 'Firm extensor-surface nodules with central fibrinoid necrosis and surrounding palisading histiocytes on biopsy',[
 ('Needle-shaped negatively birefringent crystals from the lesion','This supports a gouty tophus.'),('Rhomboid weakly positively birefringent crystals in cartilage','This supports calcium pyrophosphate deposition.'),('Caseating granulomas with identified mycobacteria','This supports mycobacterial infection, not a rheumatoid nodule.')],
 'Use morphology to separate nodular mimics','**A rheumatoid nodule characteristically has central fibrinoid necrosis with a palisading granulomatous reaction.**',['Common sites include pressure and extensor surfaces.','Not every subcutaneous nodule in RA is rheumatoid; infection, gout and other lesions remain possible.'], '**Investigate an atypical, rapidly changing or ulcerated lesion.**',['Clinical history and pathology should be correlated.','A medication review is relevant when nodules accelerate during otherwise improved joint disease.'],[['Rheumatoid nodule','Palisading histiocytes/fibrinoid center'],['Tophus','Monosodium urate crystals'],['Infectious granuloma','Organism-directed evaluation']],[ref('Rheumatoid nodule pathology','https://dermnetnz.org/topics/rheumatoid-nodule-pathology')])

if __name__=='__main__':finalize('Rheumatology',1,'Rheumatoid Arthritis','rheum-ra',rows,36)
